def puis(xx,yy):
    if yy==0:
        return 1
    else:
        return xx * puis(xx,yy-1)
def conv_10(ch,b):
    s=0
    for i in range(len(ch)):
        if "0"<=ch[i]<="9":
            k=int(ch[i])
        else:
            k=ord(ch[i])-55
        s=s+k*puis(b,len(ch)-i-1)
    return s
